import { useState } from "react";

export function DirtyState({
  label = "{{label}}",
  value = "{{value}}",
  accent = "{{accent}}",
  force = {{force}},
}) {
  const [current, setCurrent] = useState(value);
  const dirty = force || current !== value;
  return (
    <div>
      <label style={{ display: "block", width: 280, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "16px 18px", borderRadius: 12 }}>
        <span style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 7, fontSize: 12, fontWeight: 600, color: "#241430aa" }}>
          {label}
          {dirty && <span aria-hidden="true" style={{ width: 7, height: 7, borderRadius: "50%", background: accent, display: "inline-block" }} />}
        </span>
        <input type="text" value={current} onChange={(e) => setCurrent(e.target.value)}
          style={{ width: "100%", boxSizing: "border-box", font: "14px system-ui, sans-serif", padding: "9px 11px", borderRadius: 8, border: `1.5px solid ${dirty ? accent : "#24143030"}` }} />
      </label>
      <p style={{ width: 280, margin: "8px 0 0", fontSize: 11, color: "#241430888" }}>Type to change the value — a dot marks unsaved changes. The <code>force</code> prop forces it for inspection.</p>
    </div>
  );
}
